const fs=require('fs'),path=require('path'),http=require('http'),crypto=require('crypto');
const express=require('express');const {WebSocketServer}=require('ws');
let pgPool=null,saveQueue=Promise.resolve();
const app=express(),server=http.createServer(app),wss=new WebSocketServer({server,maxPayload:64*1024});
app.set('trust proxy', 1);
app.disable('x-powered-by');
const PORT=Number(process.env.PORT||8080),DB_FILE=process.env.DB_FILE||path.join(__dirname,'..','data','db.json'),APP_NAMESPACE=String(process.env.APP_NAMESPACE||'ureyimsen-web-v26');
const allowed=(process.env.CORS_ORIGINS||'https://ureyimsen.com,https://www.ureyimsen.com,http://localhost:8080,http://localhost:3000').split(',').map(s=>s.trim());
app.use((req,res,next)=>{const o=req.headers.origin;if(!o||allowed.includes(o))res.setHeader('Access-Control-Allow-Origin',o||'*');res.setHeader('Vary','Origin');res.setHeader('Access-Control-Allow-Headers','Content-Type,Authorization');res.setHeader('Access-Control-Allow-Methods','GET,POST,PUT,DELETE,OPTIONS');if(req.method==='OPTIONS')return res.sendStatus(204);next()});
app.use(express.json({limit:'4mb'}));
app.get('/api/railway-status',(q,r)=>r.json({ok:true,platform:'railway',port:PORT,websocket:true,production:process.env.NODE_ENV==='production',database:process.env.DATABASE_URL?'postgres':'file'}));app.use(express.static(path.join(__dirname,'..','public')));
function emptyDb(){return {users:{},sessions:{},rooms:{},wallets:{},messages:[],transactions:[],gifts:[],pk:{},moments:[],follows:{},notifications:{},ludo:{},calls:{},redEnvelopes:{},idempotency:{}}}
function load(){try{return JSON.parse(fs.readFileSync(DB_FILE,'utf8'))}catch{return emptyDb()}}
let db=load();for(const k of ['users','rooms','wallets','messages','transactions','gifts','pk','moments','follows','notifications','ludo','calls','redEnvelopes','idempotency'])if(!db[k])db[k]=k==='messages'||k==='transactions'||k==='moments'?[]:{};
function save(){const snapshot=JSON.stringify(db);if(!pgPool){fs.mkdirSync(path.dirname(DB_FILE),{recursive:true});fs.writeFileSync(DB_FILE,snapshot);return Promise.resolve()}saveQueue=saveQueue.then(()=>pgPool.query('INSERT INTO app_state(key,data,updated_at) VALUES($1,$2::jsonb,NOW()) ON CONFLICT(key) DO UPDATE SET data=EXCLUDED.data,updated_at=NOW()',[APP_NAMESPACE,snapshot])).catch(e=>console.error('database save failed',e.message));return saveQueue}
function sessionUserId(token){const sess=db.sessions[token];const id=typeof sess==='string'?sess:sess?.userId;const exp=typeof sess==='object'?Number(sess.expiresAt||0):0;if(!id||(exp&&exp<Date.now()))return null;return id}
function auth(req,res,next){const h=String(req.headers.authorization||'');const token=h.startsWith('Bearer ')?h.slice(7):'';const sess=db.sessions[token];const id=typeof sess==='string'?sess:sess?.userId;const exp=typeof sess==='object'?Number(sess.expiresAt||0):0;if(!token||!id||!db.users[id]||(exp&&exp<Date.now())){if(token&&exp&&exp<Date.now()){delete db.sessions[token];save()}return res.status(401).json({error:'unauthorized'})}req.user=db.users[id];req.sessionToken=token;next()}
function safeUser(u){const x={...u};delete x.passwordHash;return x}
function sameUser(req,id){return req.user&&req.user.id===String(id)}
function roomMember(roomId,userId){const x=db.rooms[roomId];return !!(x&&x.viewers&&x.viewers[userId])}
function roomHost(roomId,userId){const x=db.rooms[roomId];return !!(x&&x.host===userId)}
function roomModerator(roomId,userId){const x=db.rooms[roomId];return !!(x&&(x.host===userId||(x.admins||[]).includes(userId)))}
function requireRoomModerator(req,res,next){const id=req.params.id||req.body?.roomId;if(!db.rooms[id]||db.rooms[id].closed)return res.status(404).json({error:'room_not_found'});if(!roomModerator(id,req.user.id))return res.status(403).json({error:'moderator_required'});next()}
function requireRoomHost(req,res,next){const id=req.params.id||req.body?.roomId;if(!db.rooms[id]||db.rooms[id].closed)return res.status(404).json({error:'room_not_found'});if(!roomHost(id,req.user.id))return res.status(403).json({error:'host_required'});next()}
function clampInt(v,min,max,d=min){const n=Number(v);return Number.isInteger(n)?Math.max(min,Math.min(max,n)):d}
function cleanText(v,n=500){return String(v??'').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').slice(0,n)}
function requestKey(req){const k=String(req.headers['idempotency-key']||'').trim();return k&&k.length<=128?k:''}
function cachedResponse(req,userId){const k=requestKey(req);return k?db.idempotency[userId+':'+k]:null}
function cacheResponse(req,userId,payload){const k=requestKey(req);if(!k)return;db.idempotency[userId+':'+k]={at:Date.now(),payload};const keys=Object.keys(db.idempotency);if(keys.length>5000){for(const key of keys.sort((a,b)=>db.idempotency[a].at-db.idempotency[b].at).slice(0,keys.length-5000))delete db.idempotency[key]}}
const gifts=[['rose','🌹','Rose',10],['heart','❤️','Heart',20],['diamond','💎','Diamond',100],['cake','🎂','Cake',250],['car','🚗','Car',500],['crown','👑','Crown',1000],['rocket','🚀','Rocket',5000],['love','💖','Love Rain',10000]];
const giftAssets={rose:'moment_like.pag',heart:'heart.pag',diamond:'vip_dynamic_avatar_sample.pag',cake:'game_point_get_money_anim.pag',car:'live_pk_start_bmp.pag',crown:'main_tab_vip.pag',rocket:'pk_win.pag',love:'super_red_packet.pag'};
function uid(){return crypto.randomUUID()}
function hashPassword(password){const salt=crypto.randomBytes(16);const hash=crypto.scryptSync(String(password),salt,64);return salt.toString('hex')+':'+hash.toString('hex')}
function verifyPassword(password,stored){try{const [s,h]=String(stored).split(':');if(!s||!h)return false;const salt=Buffer.from(s,'hex'),expected=Buffer.from(h,'hex'),actual=crypto.scryptSync(String(password),salt,expected.length);return crypto.timingSafeEqual(actual,expected)}catch{return false}}
function user(id,name){if(!db.users[id]){db.users[id]={id,name:name||'Guest',createdAt:Date.now(),vip:0,level:1,followers:0,following:0,bio:'',avatar:'',email:'',passwordHash:'',rating:0,likes:0,giftsReceived:0,giftsSent:0};db.wallets[id]={coins:0};db.notifications[id]=[];save()}return db.users[id]}
function normalizeRoom(x){if(!x)return x;x.viewers=x.viewers||{};x.seats=Array.isArray(x.seats)?x.seats.slice(0,12):[];while(x.seats.length<12)x.seats.push(null);x.admins=Array.isArray(x.admins)?x.admins:[];x.banned=Array.isArray(x.banned)?x.banned:[];x.seatRequests=x.seatRequests||{};x.seatLocks=Array.isArray(x.seatLocks)?x.seatLocks.slice(0,12):[];while(x.seatLocks.length<12)x.seatLocks.push(false);x.micMuted=x.micMuted||{};x.kickHistory=Array.isArray(x.kickHistory)?x.kickHistory:[];x.announcement=cleanText(x.announcement||'',500);x.cover=cleanText(x.cover||'',1000);x.tags=Array.isArray(x.tags)?x.tags.slice(0,5).map(v=>cleanText(v,30)):[];return x}
function normalizeAllRooms(){for(const x of Object.values(db.rooms||{}))normalizeRoom(x)}
normalizeAllRooms();
function room(id){if(!db.rooms[id])db.rooms[id]={id,title:'Xena Room',type:'video',host:null,viewers:{},seats:Array(12).fill(null),admins:[],banned:[],locked:false,seatMode:'open',seatRequests:{},seatLocks:Array(12).fill(false),micMuted:{},kickHistory:[],announcement:'',cover:'',tags:[],createdAt:Date.now(),music:null};return normalizeRoom(db.rooms[id])}
function broadcast(r,msg){for(const c of wss.clients)if(c.readyState===1&&c.roomId===r)c.send(JSON.stringify(msg))}
function notify(id,n){if(!db.notifications[id])db.notifications[id]=[];const item={id:uid(),at:Date.now(),read:false,...n};db.notifications[id].unshift(item);db.notifications[id]=db.notifications[id].slice(0,200);for(const c of wss?.clients||[])if(c.readyState===1&&c.userId===id)c.send(JSON.stringify({type:'notification',notification:item}))}
app.get('/health',(q,r)=>r.json({ok:true,service:'xena-web',time:new Date().toISOString()}));
setInterval(()=>{let changed=false;const now=Date.now();for(const [token,s] of Object.entries(db.sessions)){const exp=typeof s==='object'?Number(s.expiresAt||0):0;if(exp&&exp<now){delete db.sessions[token];changed=true}}for(const [key,v] of Object.entries(db.idempotency||{})){if(!v||now-Number(v.at||0)>24*60*60*1000){delete db.idempotency[key];changed=true}}if(changed)save()},10*60*1000);
setInterval(()=>{const cutoff=Date.now()-1000*60*60*24;let changed=false;for(const x of Object.values(db.rooms)){if(x.closed||x.viewers&&Object.keys(x.viewers).length)continue;if(x.createdAt<cutoff){x.closed=true;x.closedAt=Date.now();changed=true}}if(changed)save()},10*60*1000);
app.get('/api/config',(q,r)=>r.json({version:'v26',origin:'ureyimsen.com',apiBase:'/api',allowedOrigins:allowed,developmentRecharge:process.env.ALLOW_DEV_RECHARGE==='true',features:{video:true,audio:true,gifts:true,pk:true,pkInvites:true,ludo:true,moments:true,vip:true,wallet:true,notifications:true,privateLink:true,roomAnnouncement:true,seatControl:true,redEnvelope:true},media:{mode:process.env.LIVEKIT_URL?'livekit':'mesh',livekitUrl:process.env.LIVEKIT_URL||null},webrtc:{iceServers:[{urls:'stun:stun.l.google.com:19302'}].concat(process.env.TURN_URL?[{urls:process.env.TURN_URL,username:process.env.TURN_USERNAME||'',credential:process.env.TURN_CREDENTIAL||''}]:[])}}));
function b64u(v){return Buffer.from(v).toString('base64').replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_')}
function livekitJwt(apiKey,secret,identity,roomName){const now=Math.floor(Date.now()/1000),header=b64u(JSON.stringify({alg:'HS256',typ:'JWT'})),payload=b64u(JSON.stringify({iss:apiKey,sub:identity,nbf:now-5,exp:now+3600,video:{roomJoin:true,room:roomName,canPublish:true,canSubscribe:true,canPublishData:true}})),data=header+'.'+payload,sig=crypto.createHmac('sha256',secret).update(data).digest('base64').replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');return data+'.'+sig}
app.post('/api/livekit/token',auth,(q,r)=>{const url=String(process.env.LIVEKIT_URL||'').trim(),key=String(process.env.LIVEKIT_API_KEY||''),secret=String(process.env.LIVEKIT_API_SECRET||''),roomName=String(q.body?.roomId||'').trim();if(!url||!key||!secret)return r.status(503).json({error:'livekit_not_configured'});if(!roomName||!db.rooms[roomName])return r.status(404).json({error:'room_not_found'});const x=db.rooms[roomName];if(x.banned.includes(q.user.id)||x.locked&&x.host!==q.user.id)return r.status(403).json({error:x.banned.includes(q.user.id)?'banned':'room_locked'});r.json({url,token:livekitJwt(key,secret,q.user.id,roomName),roomId:roomName,identity:q.user.id})});
app.post('/api/rooms/:id/seat-mode',auth,requireRoomHost,(q,r)=>{const x=db.rooms[q.params.id],mode=String(q.body?.mode||'open');if(!x||x.closed)return r.status(404).json({error:'room_not_found'});if(!['open','request','host_only'].includes(mode))return r.status(400).json({error:'invalid_seat_mode'});x.seatMode=mode;save();broadcast(x.id,{type:'room',room:x});r.json(x)});
app.post('/api/rooms/:id/seat-request',auth,(q,r)=>{const x=db.rooms[q.params.id],uid0=q.user.id;if(!x||x.closed)return r.status(404).json({error:'room_not_found'});;if(!roomMember(x.id,uid0)||x.host===uid0)return r.status(403).json({error:'room_required'});if(x.banned.includes(uid0))return r.status(403).json({error:'banned'});if((x.seatMode||'open')!=='request')return r.status(409).json({error:'seat_requests_disabled'});x.seatRequests=x.seatRequests||{};const existing=x.seatRequests[uid0];if(existing?.status==='pending')return r.json(existing);const req={id:uid(),userId:uid0,name:q.user.name,seat:clampInt(q.body?.seat,0,11,0),status:'pending',createdAt:Date.now()};x.seatRequests[uid0]=req;notify(x.host,{type:'seat_request',roomId:x.id,request:req});save();broadcast(x.id,{type:'seat_request',request:req});r.json(req)});
app.post('/api/rooms/:id/seat-request/:userId',auth,requireRoomHost,(q,r)=>{const x=normalizeRoom(db.rooms[q.params.id]);if(!x||x.closed)return r.status(404).json({error:'room_not_found'});const target=String(q.params.userId),req=x.seatRequests?.[target],action=String(q.body?.action||'');if(!req)return r.status(404).json({error:'request_not_found'});if(!['accept','decline'].includes(action))return r.status(400).json({error:'invalid_action'});if(action==='accept'){const i=clampInt(req.seat,0,11,-1);if(i<0)return r.status(400).json({error:'invalid_seat'});if(x.seatLocks[i])return r.status(409).json({error:'seat_locked'});if(x.seats[i]&&x.seats[i].userId!==target)return r.status(409).json({error:'seat_taken'});x.seats=x.seats.map((v,n)=>n===i?{userId:target,name:db.users[target]?.name||req.name}:(v?.userId===target?null:v));}req.status=action==='accept'?'accepted':'declined';req.resolvedAt=Date.now();notify(target,{type:'seat_request_result',roomId:x.id,request:req});save();broadcast(x.id,{type:'seat_request_result',request:req,room:x});r.json(req)});
app.get('/api/gifts',(q,r)=>r.json(gifts.map(([id,icon,name,price])=>({id,icon,name,price,asset:giftAssets[id]}))));
app.get('/api/gifts/banner',(q,r)=>r.json({title:'Hədiyyələr',items:gifts.map(([id,icon,name,price])=>({id,icon,name,price,asset:giftAssets[id]}))}));
