app.get('/api/gifts/history',auth,(q,r)=>{const roomId=String(q.query.roomId||'');const rows=db.gifts.filter(x=>(!roomId||x.roomId===roomId)&&(x.userId===q.user.id||x.toUserId===q.user.id)).slice(-200).reverse();r.json(rows)});
const httpRate=new Map();
function httpLimited(req,key,max,windowMs){const ip=String(req.ip||req.headers['x-forwarded-for']||'unknown').split(',')[0].trim();const k=ip+':'+key;const now=Date.now();let a=httpRate.get(k)||[];a=a.filter(t=>now-t<windowMs);if(a.length>=max){httpRate.set(k,a);return false}a.push(now);httpRate.set(k,a);return true}
app.post('/api/auth/guest',(q,r)=>{if(!httpLimited(q,'guest',10,60000))return r.status(429).json({error:'rate_limited'});const id=uid(),token=crypto.randomBytes(32).toString('hex'),u=user(id,String(q.body?.name||'Guest').slice(0,32));db.sessions[token]={userId:id,expiresAt:Date.now()+1000*60*60*24*30};save();r.json({token,user:safeUser(u),wallet:db.wallets[id]})});
app.post('/api/auth/register',(q,r)=>{if(!httpLimited(q,'register',8,60000))return r.status(429).json({error:'rate_limited'});const email=String(q.body?.email||'').trim().toLowerCase();const password=String(q.body?.password||'');const name=cleanText(q.body?.name||'User',32);if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)||password.length<6)return r.status(400).json({error:'invalid_credentials'});if(Object.values(db.users).some(u=>u.email===email))return r.status(409).json({error:'email_exists'});const id=uid(),u=user(id,name);u.email=email;u.passwordHash=hashPassword(password);const token=crypto.randomBytes(32).toString('hex');db.sessions[token]={userId:id,expiresAt:Date.now()+1000*60*60*24*30};save();r.json({token,user:safeUser(u),wallet:db.wallets[id]})});
app.post('/api/auth/login',(q,r)=>{if(!httpLimited(q,'login',12,60000))return r.status(429).json({error:'rate_limited'});const email=String(q.body?.email||'').trim().toLowerCase(),password=String(q.body?.password||'');const u=Object.values(db.users).find(x=>x.email===email);if(!u||!verifyPassword(password,u.passwordHash))return r.status(401).json({error:'invalid_credentials'});const token=crypto.randomBytes(32).toString('hex');db.sessions[token]={userId:u.id,expiresAt:Date.now()+1000*60*60*24*30};save();r.json({token,user:safeUser(u),wallet:db.wallets[u.id]})});
app.post('/api/auth/logout',auth,(q,r)=>{delete db.sessions[q.sessionToken];save();r.json({ok:true})});
app.get('/api/rooms',(q,r)=>r.json(Object.values(db.rooms).filter(x=>!x.closed).map(x=>({...x,viewerCount:Object.keys(x.viewers).length,seatCount:x.seats.filter(Boolean).length}))));
app.post('/api/rooms/:id/close',auth,requireRoomHost,(q,r)=>{const x=db.rooms[q.params.id];x.closed=true;x.closedAt=Date.now();save();broadcast(x.id,{type:'room_closed',roomId:x.id});r.json({ok:true,room:x})});
app.post('/api/rooms/:id/host-transfer',auth,requireRoomHost,(q,r)=>{const x=db.rooms[q.params.id],to=String(q.body?.userId||'');if(!x.viewers[to])return r.status(400).json({error:'target_not_in_room'});const old=x.host;x.host=to;for(const v of Object.values(x.viewers))v.host=v.userId===to;save();broadcast(x.id,{type:'room',room:x});r.json({ok:true,oldHost:old,host:to,room:x})});

app.post('/api/rooms',auth,(q,r)=>{const id=uid(),x=room(id);x.title=cleanText(q.body?.title||'Xena Room',80);x.type=['video','audio'].includes(q.body?.type)?q.body.type:'video';x.host=q.user.id;x.viewers[q.user.id]={userId:q.user.id,name:q.user.name,joinedAt:Date.now(),host:true};save();r.json(x)});
