app.post('/api/rooms/:id/join',auth,(q,r)=>{const x=normalizeRoom(db.rooms[q.params.id]);if(!x||x.closed)return r.status(404).json({error:'room_not_found'});if(x.banned.includes(q.user.id))return r.status(403).json({error:'banned'});if(x.locked&&x.host!==q.user.id)return r.status(403).json({error:'room_locked'});if(!x.viewers[q.user.id]&&Object.keys(x.viewers).length>=1000)return r.status(409).json({error:'room_full'});const existed=!!x.viewers[q.user.id];if(!existed)x.viewers[q.user.id]={userId:q.user.id,name:q.user.name,joinedAt:Date.now(),host:x.host===q.user.id};save();if(!existed)broadcast(x.id,{type:'presence',action:'join',user:x.viewers[q.user.id],room:x});r.json(x)});
app.get('/api/rooms/:id/viewers',(q,r)=>{const x=db.rooms[q.params.id];if(!x)return r.status(404).json({error:'room_not_found'});r.json(Object.values(x.viewers||{}).map(v=>({...v,user:db.users[v.userId]?safeUser(db.users[v.userId]):null,seat:(x.seats||[]).findIndex(s=>s?.userId===v.userId)})))});
app.get('/api/rooms/:id/config',(q,r)=>{const x=normalizeRoom(db.rooms[q.params.id]);if(!x)return r.status(404).json({error:'room_not_found'});r.json({roomId:x.id,type:x.type,title:x.title,announcement:x.announcement,cover:x.cover,tags:x.tags,seatCount:x.seats.length,maxViewers:1000,locked:x.locked,music:x.music,seatMode:x.seatMode||'open',seatLocks:x.seatLocks,micMuted:x.micMuted,admins:x.admins||[],features:{chat:true,gifts:true,pk:true,seats:true,redEnvelope:true,video:x.type==='video',audio:true}})});
app.get('/api/rooms/:id/messages',auth,(q,r)=>{const x=db.rooms[q.params.id];if(!x)return r.status(404).json({error:'room_not_found'});if(!roomMember(x.id,q.user.id)&&!roomHost(x.id,q.user.id))return r.status(403).json({error:'room_required'});const limit=clampInt(q.query?.limit,1,200,100);r.json(db.messages.filter(m=>m.roomId===x.id).slice(-limit).map(m=>({...m,name:db.users[m.userId]?.name||'Guest',vip:db.users[m.userId]?.vip||0})))})
app.put('/api/rooms/:id',auth,requireRoomHost,(q,r)=>{
 const x=normalizeRoom(db.rooms[q.params.id]);
 if(!x||x.closed)return r.status(404).json({error:'room_not_found'});
 if(q.body?.title!==undefined)x.title=cleanText(q.body.title,80)||x.title;
 if(q.body?.type!==undefined&&['video','audio'].includes(q.body.type))x.type=q.body.type;
 if(q.body?.locked!==undefined)x.locked=!!q.body.locked;
 if(q.body?.announcement!==undefined)x.announcement=cleanText(q.body.announcement,500);
 if(q.body?.cover!==undefined)x.cover=cleanText(q.body.cover,1000);
 if(q.body?.tags!==undefined)x.tags=Array.isArray(q.body.tags)?q.body.tags.slice(0,5).map(v=>cleanText(v,30)).filter(Boolean):[];
 if(q.body?.music!==undefined){
  if(q.body.music===null)x.music=null;
  else{
   const u=cleanText(q.body.music?.url,1000);
   try{const parsed=new URL(u);if(!['http:','https:'].includes(parsed.protocol))throw Error('protocol')}catch{return r.status(400).json({error:'invalid_music_url'})}
   x.music={title:cleanText(q.body.music?.title,120),url:u};
  }
 }
 save();broadcast(x.id,{type:'room',room:x});r.json(x);
});
app.post('/api/rooms/:id/admins',auth,requireRoomHost,(q,r)=>{const x=db.rooms[q.params.id];if(!x||x.closed)return r.status(404).json({error:'room_not_found'});const target=String(q.body?.userId||'');if(!db.users[target])return r.status(404).json({error:'user_not_found'});if(target===x.host)return r.status(400).json({error:'host_is_not_admin'});if(!x.admins.includes(target))x.admins.push(target);save();notify(target,{type:'room_admin',roomId:x.id,role:'admin'});broadcast(x.id,{type:'room',room:x});r.json({admins:x.admins})})
app.delete('/api/rooms/:id/admins/:userId',auth,requireRoomHost,(q,r)=>{const x=db.rooms[q.params.id];if(!x||x.closed)return r.status(404).json({error:'room_not_found'});x.admins=x.admins.filter(id=>id!==String(q.params.userId));save();broadcast(x.id,{type:'room',room:x});r.json({admins:x.admins})})
app.post('/api/rooms/:id/moderation',auth,requireRoomModerator,(q,r)=>{const x=normalizeRoom(db.rooms[q.params.id]);if(!x||x.closed)return r.status(404).json({error:'room_not_found'});const target=String(q.body?.userId||''),action=String(q.body?.action||'');if(!target||!['kick','ban','unban'].includes(action))return r.status(400).json({error:'invalid_moderation'});if(target===x.host)return r.status(400).json({error:'cannot_moderate_host'});if(action==='ban'){if(!x.banned.includes(target))x.banned.push(target);delete x.viewers[target];x.seats=x.seats.map(v=>v?.userId===target?null:v);notify(target,{type:'room_ban',roomId:x.id})}else if(action==='unban'){x.banned=x.banned.filter(id=>id!==target)}else{delete x.viewers[target];x.seats=x.seats.map(v=>v?.userId===target?null:v);notify(target,{type:'room_kick',roomId:x.id})}x.kickHistory.unshift({id:uid(),userId:target,action,by:q.user.id,at:Date.now()});x.kickHistory=x.kickHistory.slice(0,200);save();for(const c of wss.clients)if(c.readyState===1&&c.roomId===x.id&&c.userId===target&&['kick','ban'].includes(action))c.close(4003,action);broadcast(x.id,{type:'room',room:x});r.json({ok:true,action,userId:target})})
app.delete('/api/rooms/:id/messages/:messageId',auth,requireRoomModerator,(q,r)=>{const x=db.rooms[q.params.id];if(!x||x.closed)return r.status(404).json({error:'room_not_found'});const m=db.messages.find(v=>v.id===q.params.messageId&&v.roomId===x.id);if(!m)return r.status(404).json({error:'message_not_found'});m.deleted=true;m.text='[Mesaj silindi]';m.deletedAt=Date.now();m.deletedBy=q.user.id;save();broadcast(x.id,{type:'message_deleted',messageId:m.id});r.json({ok:true,messageId:m.id})})
app.delete('/api/rooms/:id/messages',auth,requireRoomModerator,(q,r)=>{const x=db.rooms[q.params.id];if(!x||x.closed)return r.status(404).json({error:'room_not_found'});for(const m of db.messages.filter(v=>v.roomId===x.id)){m.deleted=true;m.text='[Mesaj silindi]';m.deletedAt=Date.now();m.deletedBy=q.user.id}save();broadcast(x.id,{type:'chat_cleared'});r.json({ok:true})})
app.post('/api/rooms/:id/seat',auth,(q,r)=>{const uid0=q.user.id;const x=normalizeRoom(db.rooms[q.params.id]);if(!uid0||!x)return r.status(!x?404:401).json({error:!x?'room_not_found':'unauthorized'});if(!roomMember(x.id,uid0)&&!roomHost(x.id,uid0))return r.status(403).json({error:'room_required'});if(x.banned.includes(uid0)||x.locked&&x.host!==uid0)return r.status(403).json({error:x.banned.includes(uid0)?'banned':'room_locked'});const i=clampInt(q.body?.seat,0,x.seats.length-1,-1),take=q.body?.take!==false;if(i<0)return r.status(400).json({error:'invalid_seat'});if(take){if(x.seatLocks[i]&&!roomModerator(x.id,uid0))return r.status(409).json({error:'seat_locked'});if((x.seatMode||'open')==='host_only'&&!roomModerator(x.id,uid0))return r.status(403).json({error:'host_only'});if((x.seatMode||'open')==='request'&&!roomModerator(x.id,uid0))return r.status(409).json({error:'seat_request_required'});if(x.seats[i]&&x.seats[i].userId!==uid0)return r.status(409).json({error:'seat_taken'});x.seats=x.seats.map((v,n)=>n===i?{userId:uid0,name:db.users[uid0]?.name||'Guest'}:(v?.userId===uid0?null:v))}else if(x.seats[i]?.userId===uid0||roomModerator(x.id,uid0))x.seats[i]=null;save();broadcast(x.id,{type:'room',room:x});r.json(x)});
app.get('/api/users/search',(q,r)=>{const term=String(q.query.q||'').trim().toLowerCase();if(!term)return r.json([]);r.json(Object.values(db.users).filter(u=>u.name.toLowerCase().includes(term)||u.id.toLowerCase()===term).slice(0,30).map(u=>({id:u.id,name:u.name,vip:u.vip,level:u.level,avatar:u.avatar}))) });
app.post('/api/rooms/:id/leave',auth,(q,r)=>{const x=db.rooms[q.params.id];if(!x)return r.status(404).json({error:'room_not_found'});const uid0=q.user.id;if(uid0===x.host)return r.status(400).json({error:'host_must_close_or_transfer'});const existed=!!x.viewers[uid0];delete x.viewers[uid0];x.seats=x.seats.map(v=>v?.userId===uid0?null:v);if(x.seatRequests?.[uid0])delete x.seatRequests[uid0];save();if(existed)broadcast(x.id,{type:'presence',action:'leave',userId:uid0,room:x});r.json({ok:true,room:x})});
app.post('/api/rooms/:id/settings',auth,requireRoomHost,(q,r)=>{const x=normalizeRoom(db.rooms[q.params.id]);if(!x||x.closed)return r.status(404).json({error:'room_not_found'});if(q.body?.title!==undefined)x.title=cleanText(q.body.title,80)||x.title;if(q.body?.locked!==undefined)x.locked=!!q.body.locked;if(q.body?.announcement!==undefined)x.announcement=cleanText(q.body.announcement,500);save();broadcast(x.id,{type:'room',room:x});r.json(x)});
app.get('/api/rooms/:id/admin',auth,requireRoomModerator,(q,r)=>{const x=normalizeRoom(db.rooms[q.params.id]);if(!x||x.closed)return r.status(404).json({error:'room_not_found'});r.json({admins:x.admins,banned:x.banned,viewers:Object.values(x.viewers),seatRequests:Object.values(x.seatRequests).filter(v=>v.status==='pending'),seatLocks:x.seatLocks,micMuted:x.micMuted,kickHistory:x.kickHistory})});
app.post('/api/rooms/:id/seat-lock',auth,requireRoomModerator,(q,r)=>{const x=normalizeRoom(db.rooms[q.params.id]);if(!x||x.closed)return r.status(404).json({error:'room_not_found'});const seat=clampInt(q.body?.seat,0,11,-1);if(seat<0)return r.status(400).json({error:'invalid_seat'});x.seatLocks[seat]=q.body?.locked!==false;save();broadcast(x.id,{type:'room',room:x});r.json({seat,locked:x.seatLocks[seat],room:x})});
app.post('/api/rooms/:id/mic',auth,(q,r)=>{const x=normalizeRoom(db.rooms[q.params.id]);if(!x||x.closed)return r.status(404).json({error:'room_not_found'});const target=String(q.body?.userId||q.user.id);if(target!==q.user.id&&!roomModerator(x.id,q.user.id))return r.status(403).json({error:'moderator_required'});if(!x.viewers[target])return r.status(404).json({error:'user_not_in_room'});x.micMuted[target]=q.body?.muted!==false;save();broadcast(x.id,{type:'mic',userId:target,muted:x.micMuted[target],room:x});r.json({userId:target,muted:x.micMuted[target]})});
