app.get('/api/rooms/:id/red-envelopes',auth,(q,r)=>{const x=db.rooms[q.params.id];if(!x)return r.status(404).json({error:'room_not_found'});if(!roomMember(x.id,q.user.id)&&!roomHost(x.id,q.user.id))return r.status(403).json({error:'room_required'});r.json(Object.values(db.redEnvelopes).filter(v=>v.roomId===x.id&&v.expiresAt>Date.now()))});
app.post('/api/rooms/:id/red-envelopes',auth,(q,r)=>{const x=db.rooms[q.params.id],userId=q.user.id;if(!x)return r.status(404).json({error:'room_not_found'});if(!roomMember(x.id,userId)&&!roomHost(x.id,userId))return r.status(403).json({error:'room_required'});const coins=clampInt(q.body?.coins,1,1000000,0),shares=clampInt(q.body?.shares,1,100,0);if(!coins||!shares||shares>coins)return r.status(400).json({error:'invalid_red_envelope'});if((db.wallets[userId]?.coins||0)<coins)return r.status(400).json({error:'insufficient_coins'});db.wallets[userId].coins-=coins;const item={id:uid(),roomId:x.id,userId,coins,remainingCoins:coins,shares,remainingShares:shares,claims:[],createdAt:Date.now(),expiresAt:Date.now()+600000};db.redEnvelopes[item.id]=item;db.transactions.push({id:uid(),type:'red_envelope_create',userId,roomId:x.id,coins,at:Date.now()});save();broadcast(x.id,{type:'red_envelope',action:'created',envelope:{...item,claims:[]}});r.json({envelope:item,wallet:db.wallets[userId]})});
app.post('/api/rooms/:id/red-envelopes/:envelopeId/claim',auth,(q,r)=>{const x=db.rooms[q.params.id],item=db.redEnvelopes[q.params.envelopeId],userId=q.user.id;if(!x||!item||item.roomId!==q.params.id)return r.status(404).json({error:'red_envelope_not_found'});if(!roomMember(x.id,userId)&&!roomHost(x.id,userId))return r.status(403).json({error:'room_required'});if(item.expiresAt<=Date.now()||item.remainingShares<=0)return r.status(409).json({error:'red_envelope_closed'});const prior=item.claims.find(c=>c.userId===userId);if(prior)return r.status(409).json({error:'already_claimed',claim:prior});const amount=item.remainingShares===1?item.remainingCoins:Math.max(1,Math.floor(item.remainingCoins/item.remainingShares));const claim={userId,name:q.user.name,coins:amount,at:Date.now()};item.claims.push(claim);item.remainingCoins-=amount;item.remainingShares--;db.wallets[userId].coins+=amount;db.transactions.push({id:uid(),type:'red_envelope_claim',userId,roomId:x.id,envelopeId:item.id,coins:amount,at:Date.now()});save();broadcast(x.id,{type:'red_envelope',action:'claimed',envelopeId:item.id,claim});r.json({claim,envelope:item,wallet:db.wallets[userId]})});
