app.post('/api/gifts/send',auth,(q,r)=>{const {roomId,giftId,toSeat,quantity=1}=q.body||{},userId=q.user.id,g=gifts.find(x=>x[0]===giftId);const cached=cachedResponse(q,userId);if(cached)return r.json(cached.payload);if(!roomId||!db.rooms[roomId])return r.status(404).json({error:'room_not_found'});if(!roomMember(roomId,userId)&&!roomHost(roomId,userId))return r.status(403).json({error:'room_required'});if(!g)return r.status(404).json({error:'gift_not_found'});user(userId);const qty=Math.max(1,Math.min(999,Number(quantity)||1)),cost=g[3]*qty;if((db.wallets[userId]?.coins||0)<cost)return r.status(400).json({error:'insufficient_coins'});db.wallets[userId].coins-=cost;db.transactions.push({id:uid(),type:'gift',userId,roomId,giftId,quantity:qty,cost,at:Date.now()});const requestedSeat=Number(toSeat);const target=Number.isInteger(requestedSeat)&&requestedSeat>=0&&requestedSeat<db.rooms[roomId].seats.length?db.rooms[roomId].seats[requestedSeat]:Object.values(db.rooms[roomId].viewers||{}).find(v=>v.userId===db.rooms[roomId].host)||null;db.gifts.push({id:uid(),userId,roomId,giftId,quantity:qty,cost,toUserId:target?.userId||null,at:Date.now()});db.gifts=db.gifts.slice(-20000);db.users[userId].giftsSent=(db.users[userId].giftsSent||0)+qty;db.users[userId].rating=(db.users[userId].rating||0)+qty;if(target?.userId&&db.users[target.userId]){db.users[target.userId].giftsReceived=(db.users[target.userId].giftsReceived||0)+qty;db.users[target.userId].rating=(db.users[target.userId].rating||0)+qty*2;notify(target.userId,{type:'gift',from:userId,roomId,giftId,quantity:qty})}save();broadcast(roomId,{type:'gift',userId,giftId,toSeat,quantity:qty,cost,asset:giftAssets[giftId]});const payload={ok:true,wallet:db.wallets[userId],gift:{id:g[0],name:g[2],icon:g[1],price:g[3],asset:giftAssets[giftId]}};cacheResponse(q,userId,payload);save();r.json(payload)});
app.post('/api/gifts/combo',auth,(q,r)=>{const {roomId,giftId,toSeat,count=1}=q.body||{},userId=q.user.id;const cached=cachedResponse(q,userId);if(cached)return r.json(cached.payload);if(!roomId||!db.rooms[roomId])return r.status(404).json({error:'room_not_found'});if(!roomMember(roomId,userId)&&!roomHost(roomId,userId))return r.status(403).json({error:'room_required'});const g=gifts.find(x=>x[0]===giftId);if(!g)return r.status(404).json({error:'gift_not_found'});user(userId);const n=Math.max(1,Math.min(99,Number(count)||1)),cost=g[3]*n;if(db.wallets[userId].coins<cost)return r.status(400).json({error:'insufficient_coins'});db.wallets[userId].coins-=cost;db.users[userId].giftsSent=(db.users[userId].giftsSent||0)+n;db.users[userId].rating=(db.users[userId].rating||0)+n;const requestedSeat=Number(toSeat);const comboTarget=Number.isInteger(requestedSeat)&&requestedSeat>=0&&requestedSeat<db.rooms[roomId].seats.length?db.rooms[roomId].seats[requestedSeat]:Object.values(db.rooms[roomId].viewers||{}).find(v=>v.userId===db.rooms[roomId].host)||null;if(comboTarget?.userId&&db.users[comboTarget.userId]){db.users[comboTarget.userId].giftsReceived=(db.users[comboTarget.userId].giftsReceived||0)+n;db.users[comboTarget.userId].rating=(db.users[comboTarget.userId].rating||0)+n*2;notify(comboTarget.userId,{type:'gift',from:userId,roomId,giftId,quantity:n,combo:true})}db.transactions.push({id:uid(),type:'gift_combo',userId,roomId,giftId,quantity:n,cost,at:Date.now()});const event={id:uid(),userId,roomId,giftId,toSeat,quantity:n,cost,asset:giftAssets[giftId],combo:true};db.gifts.push({id:event.id,userId,roomId,giftId,quantity:n,cost,toUserId:comboTarget?.userId||null,combo:true,at:Date.now()});db.gifts=db.gifts.slice(-20000);broadcast(roomId,{type:'gift',...event});const payload={ok:true,wallet:db.wallets[userId],event};cacheResponse(q,userId,payload);save();r.json(payload)});
app.post('/api/vip/buy',auth,(q,r)=>{const {level=1}=q.body||{},userId=q.user.id;user(userId);const l=Math.max(1,Math.min(10,Number(level)||1)),cost=l*5000;if(db.wallets[userId].coins<cost)return r.status(400).json({error:'insufficient_coins'});db.wallets[userId].coins-=cost;db.users[userId].vip=Math.max(db.users[userId].vip,l);db.transactions.push({id:uid(),type:'vip',userId,level:l,cost,at:Date.now()});save();return r.json({user:db.users[userId],wallet:db.wallets[userId]})});
