app.post('/api/pk/start',auth,(q,r)=>{const {roomId,to}=q.body||{};if(!roomHost(roomId,q.user.id))return r.status(403).json({error:'host_required'});const x=db.rooms[roomId],from=q.user.id,target=String(to||'');if(!x)return r.status(404).json({error:'room_not_found'});if(!target||target===from||!x.viewers[target])return r.status(400).json({error:'invalid_opponent'});const current=db.pk[roomId];if(current&&['invited','active'].includes(current.status))return r.status(409).json({error:'pk_busy'});db.pk[roomId]={id:uid(),status:'invited',from,to:target,a:0,b:0,invitedAt:Date.now(),expiresAt:Date.now()+60000,duration:300};notify(target,{type:'pk_invite',roomId,from,pkId:db.pk[roomId].id});save();broadcast(roomId,{type:'pk',pk:db.pk[roomId]});r.json(db.pk[roomId])});
app.post('/api/pk/:roomId/respond',auth,(q,r)=>{const pk=db.pk[q.params.roomId],action=String(q.body?.action||'');if(!pk||pk.status!=='invited')return r.status(404).json({error:'pk_invite_not_found'});if(pk.to!==q.user.id)return r.status(403).json({error:'pk_target_required'});if(pk.expiresAt<Date.now()){pk.status='expired';save();return r.status(409).json({error:'pk_invite_expired'})}if(!['accept','decline'].includes(action))return r.status(400).json({error:'invalid_action'});pk.status=action==='accept'?'active':'declined';pk.respondedAt=Date.now();if(pk.status==='active')pk.startedAt=Date.now();save();broadcast(q.params.roomId,{type:'pk',pk});r.json(pk)});
app.post('/api/pk/:roomId/cancel',auth,(q,r)=>{const pk=db.pk[q.params.roomId];if(!pk||pk.status!=='invited')return r.status(404).json({error:'pk_invite_not_found'});if(pk.from!==q.user.id)return r.status(403).json({error:'pk_inviter_required'});pk.status='cancelled';pk.cancelledAt=Date.now();save();broadcast(q.params.roomId,{type:'pk',pk});r.json(pk)});
app.post('/api/pk/score',auth,(q,r)=>{const {roomId,side,points}=q.body||{},pk=db.pk[roomId];if(!pk||pk.status!=='active')return r.status(404).json({error:'no_pk'});if(Date.now()-pk.startedAt>pk.duration*1000){pk.status='ended';pk.endedAt=Date.now();save();broadcast(roomId,{type:'pk',pk});return r.status(409).json({error:'pk_expired',pk})}const wanted=side==='b'?'b':'a',actor=q.user.id;if((wanted==='a'&&actor!==pk.from)||(wanted==='b'&&actor!==pk.to))return r.status(403).json({error:'pk_side_forbidden'});const n=Math.max(0,Math.min(100000,Number(points)||0));pk[wanted]+=n;save();broadcast(roomId,{type:'pk',pk});r.json(pk)});
app.post('/api/pk/end',auth,(q,r)=>{if(!roomHost(q.body?.roomId,q.user.id))return r.status(403).json({error:'host_required'});if(!db.pk[q.body?.roomId])return r.status(404).end();db.pk[q.body.roomId].status='ended';db.pk[q.body.roomId].endedAt=Date.now();save();broadcast(q.body.roomId,{type:'pk',pk:db.pk[q.body.roomId]});r.json(db.pk[q.body.roomId])});
app.get('/api/pk/:roomId',(q,r)=>r.json(db.pk[q.params.roomId]||null));
app.post('/api/private-link/request',auth,(q,r)=>{const {to,roomId}=q.body||{};const from=q.user.id;if(!to||from===to||!db.users[to])return r.status(400).json({error:'invalid_call'});if(roomId){const x=db.rooms[roomId];if(!x)return r.status(404).json({error:'room_not_found'});if(x.banned.includes(from)||x.banned.includes(String(to)))return r.status(403).json({error:'banned'});if(!roomMember(roomId,from)||!roomMember(roomId,String(to)))return r.status(403).json({error:'room_required'})}const id=uid();db.calls[id]={id,from,to,roomId,status:'ringing',createdAt:Date.now()};notify(to,{type:'private_call',callId:id,from,roomId});save();r.json(db.calls[id])});
app.post('/api/private-link/:id',auth,(q,r)=>{const c=db.calls[q.params.id];if(!c||![c.from,c.to].includes(q.user.id))return r.status(c?403:404).json({error:c?'forbidden':'not_found'});if(!c)return r.status(404).end();c.status=['accept','decline','end'].includes(q.body?.action)?q.body.action:c.status;save();if(c.roomId)broadcast(c.roomId,{type:'private_link',call:c});r.json(c)});
app.get('/api/ludo/:roomId',(q,r)=>r.json(db.ludo[q.params.roomId]||null));
function newLudo(id,mode='classic'){return {roomId:id,mode:mode==='2v2'?'2v2':'classic',status:'waiting',players:[],turn:0,lastRoll:null,lastUser:null,winner:null,createdAt:Date.now(),board:{}}}
app.post('/api/ludo/:roomId/start',auth,(q,r)=>{const id=q.params.roomId;if(!roomMember(id,q.user.id)&&!roomHost(id,q.user.id))return r.status(403).json({error:'room_required'});const current=db.ludo[id];if(current&&(current.status==='active'||current.status==='waiting')&&current.owner!==q.user.id)return r.status(403).json({error:'ludo_owner_required'});db.ludo[id]=newLudo(id,q.body?.mode);db.ludo[id].owner=q.user.id;save();broadcast(id,{type:'ludo',game:db.ludo[id]});r.json(db.ludo[id])});
app.post('/api/ludo/:roomId/join',auth,(q,r)=>{const id=q.params.roomId;if(!roomMember(id,q.user.id)&&!roomHost(id,q.user.id))return r.status(403).json({error:'room_required'});const existing=db.ludo[id];if(existing?.status==='ended')return r.status(409).json({error:'game_ended'});const g=existing||newLudo(id);const uid0=q.user.id;if(!uid0)return r.status(400).json({error:'user_required'});const u=user(uid0);if(!g.players.some(x=>x.userId===u.id)&&g.players.length<4){const idx=g.players.length;g.players.push({userId:u.id,name:u.name,color:['red','blue','green','yellow'][idx],team:g.mode==='2v2'?(idx%2===0?'A':'B'):null,position:-1,finished:0,score:0})}if(g.players.length>=(g.mode==='2v2'?4:2))g.status='active';db.ludo[id]=g;save();broadcast(id,{type:'ludo',game:g});r.json(g)});
app.post('/api/ludo/:roomId/roll',auth,(q,r)=>{const g=db.ludo[q.params.roomId],uid0=q.user.id;if(!g||g.status!=='active')return r.status(400).json({error:'game_not_active'});if(g.players[g.turn]?.userId!==uid0)return r.status(403).json({error:'not_your_turn'});const n=1+Math.floor(Math.random()*6),p=g.players[g.turn];g.lastRoll=n;g.lastUser=uid0;g.rollAt=Date.now();if((p.position<0&&n!==6)||(p.position>=0&&p.position+n>56)){g.lastRoll=null;g.lastUser=null;g.lastMove={userId:uid0,from:p.position,to:p.position,steps:n,skipped:true,at:Date.now()};g.turn=(g.turn+1)%g.players.length}save();broadcast(g.roomId,{type:'ludo',game:g,roll:n,skipped:!!g.lastMove?.skipped});r.json(g)});
app.post('/api/ludo/:roomId/move',auth,(q,r)=>{const g=db.ludo[q.params.roomId],uid0=q.user.id;if(!g||g.status!=='active')return r.status(400).json({error:'game_not_active'});if(g.players[g.turn]?.userId!==uid0)return r.status(403).json({error:'not_your_turn'});const p=g.players[g.turn],steps=Number(g.lastRoll);if(g.lastUser!==uid0||!steps)return r.status(400).json({error:'roll_first'});if(p.position<0&&steps!==6)return r.status(400).json({error:'need_six'});if(p.position>=0&&p.position+steps>56)return r.status(400).json({error:'exact_finish_required'});const old=p.position;p.position=p.position<0?0:p.position+steps;let captured=[];const safe=new Set([0,8,13,21,26,34,39,47]);if(p.position>=0&&p.position<56&&!safe.has(p.position)){for(const other of g.players){if(other.userId!==p.userId&&other.position===p.position&&other.position>=0&&other.position<56){other.position=-1;captured.push(other.userId)}}}g.lastMove={userId:uid0,from:old,to:p.position,steps,captured,at:Date.now()};if(p.position===56){p.finished=1;p.score+=1;g.winner=p.userId;g.status='ended'}else if(steps!==6){g.turn=(g.turn+1)%g.players.length}g.lastRoll=null;g.lastUser=null;save();broadcast(g.roomId,{type:'ludo',game:g});r.json(g)});
app.post('/api/ludo/:roomId/leave',auth,(q,r)=>{const g=db.ludo[q.params.roomId];if(!g)return r.status(404).json({error:'game_not_found'});g.players=g.players.filter(v=>v.userId!==q.user.id);if(g.owner===q.user.id)g.owner=g.players[0]?.userId||null;if(g.players.length<2&&g.status==='active')g.status='waiting';if(!g.players.length)delete db.ludo[q.params.roomId];save();broadcast(q.params.roomId,{type:'ludo',game:db.ludo[q.params.roomId]||null});r.json(db.ludo[q.params.roomId]||null)});
app.post('/api/ludo/:roomId/reset',auth,(q,r)=>{const g=db.ludo[q.params.roomId];if(!g)return r.status(404).json({error:'game_not_found'});if(g.owner!==q.user.id)return r.status(403).json({error:'ludo_owner_required'});const fresh=newLudo(q.params.roomId,g.mode);fresh.owner=q.user.id;db.ludo[q.params.roomId]=fresh;save();broadcast(q.params.roomId,{type:'ludo',game:fresh});r.json(fresh)});
wss.on('connection',(ws,req)=>{
 const origin=String(req.headers.origin||'');if(origin&&!allowed.includes(origin)){ws.close(1008,'origin_not_allowed');return}
 ws.isAlive=true;ws.authed=false;ws.rate={chat:[],signal:[],all:[]};ws.on('pong',()=>{ws.isAlive=true});
 const limited=(kind,max,windowMs)=>{const now=Date.now(),a=ws.rate[kind];while(a.length&&now-a[0]>windowMs)a.shift();if(a.length>=max)return false;a.push(now);return true};
 ws.send(JSON.stringify({type:'hello',serverTime:Date.now()}));
 ws.on('message',raw=>{let m;try{m=JSON.parse(raw)}catch{return}
  if(!limited('all',120,10000))return;
  if(m.type==='join'){
   const token=String(m.token||''); const uid0=sessionUserId(token);
   if(!uid0||!db.users[uid0])return ws.send(JSON.stringify({type:'error',error:'unauthorized'}));
   const x=normalizeRoom(db.rooms[m.roomId]); if(!x||x.closed)return ws.send(JSON.stringify({type:'error',error:'room_not_found'}));
   const u=db.users[uid0];
   if(x.banned.includes(u.id)||x.locked&&x.host!==u.id)return ws.send(JSON.stringify({type:'error',error:x.banned.includes(u.id)?'banned':'room_locked'}));
   if(!x.viewers[u.id]&&Object.keys(x.viewers).length>=1000)return ws.send(JSON.stringify({type:'error',error:'room_full'}));
   ws.authed=true;ws.sessionToken=token;ws.roomId=x.id;ws.userId=u.id;
   const wasConnected=!!x.viewers[u.id]&&Number(x.viewers[u.id].connections||0)>0;
   if(!x.viewers[u.id])x.viewers[u.id]={userId:u.id,name:u.name,joinedAt:Date.now(),host:x.host===u.id,connections:0};
   x.viewers[u.id].connections=(x.viewers[u.id].connections||0)+1;save();
   if(!wasConnected)broadcast(x.id,{type:'presence',action:'join',user:x.viewers[u.id],room:x});
   ws.send(JSON.stringify({type:'room',room:x,user:safeUser(u),wallet:db.wallets[u.id]}));
  }
  else if(m.type==='chat'&&ws.authed&&ws.roomId){if(!limited('chat',8,2000))return;const msg={id:uid(),roomId:ws.roomId,userId:ws.userId,text:cleanText(m.text),at:Date.now(),deleted:false};if(!msg.text)return;db.messages.push(msg);db.messages=db.messages.slice(-10000);save();broadcast(ws.roomId,{type:'chat',message:{...msg,name:db.users[ws.userId]?.name||'Guest',vip:db.users[ws.userId]?.vip||0}})}
  else if(m.type==='seat'&&ws.authed&&ws.roomId){const x=normalizeRoom(db.rooms[ws.roomId]),i=Number(m.seat),mod=roomModerator(ws.roomId,ws.userId);if(!x||!roomMember(x.id,ws.userId)&&x.host!==ws.userId)return;if((x.seatMode||'open')==='host_only'&&!mod)return;if((x.seatMode||'open')==='request'&&!mod)return;if(i>=0&&i<12){if(m.take&&!x.seats[i]&&(!x.seatLocks[i]||mod))x.seats[i]={userId:ws.userId,name:db.users[ws.userId]?.name};else if(!m.take&&(x.seats[i]?.userId===ws.userId||mod))x.seats[i]=null;save();broadcast(x.id,{type:'room',room:x})}}
  else if(m.type==='webrtc'&&ws.authed&&ws.roomId&&m.to){if(!limited('signal',40,1000))return;for(const c of wss.clients)if(c!==ws&&c.readyState===1&&c.roomId===ws.roomId&&c.userId===m.to)c.send(JSON.stringify({...m,from:ws.userId}))}
  else if(m.type==='typing'&&ws.authed&&ws.roomId)broadcast(ws.roomId,{type:'typing',userId:ws.userId,typing:!!m.typing})
  else if(m.type==='ping')ws.send(JSON.stringify({type:'pong',at:Date.now()}));
 });
 ws.on('close',()=>{if(ws.roomId&&db.rooms[ws.roomId]){const x=db.rooms[ws.roomId],v=x.viewers[ws.userId];if(v){v.connections=Math.max(0,(v.connections||1)-1);if(v.connections===0){delete x.viewers[ws.userId];x.seats=x.seats.map(z=>z?.userId===ws.userId?null:z);save();broadcast(ws.roomId,{type:'presence',action:'leave',userId:ws.userId,room:x})}else save()}}})
});

const heartbeat=setInterval(()=>{for(const ws of wss.clients){if(ws.isAlive===false){ws.terminate();continue}ws.isAlive=false;try{ws.ping()}catch{}}},30000);wss.on('close',()=>clearInterval(heartbeat));
process.on('uncaughtException',e=>console.error('uncaughtException',e));
process.on('unhandledRejection',e=>console.error('unhandledRejection',e));
async function shutdown(signal){
 console.log(`Received ${signal}, shutting down...`);
 try{await new Promise(resolve=>server.close(resolve));}catch{}
 try{if(pgPool)await pgPool.end();}catch{}
 process.exit(0);
}
process.once('SIGTERM',()=>shutdown('SIGTERM'));
process.once('SIGINT',()=>shutdown('SIGINT'));

async function bootstrap(){
 if(process.env.DATABASE_URL){
  try{
   const {Pool}=require('pg');
   pgPool=new Pool({connectionString:process.env.DATABASE_URL,ssl:process.env.DATABASE_URL.includes('localhost')?false:{rejectUnauthorized:false},max:5});
   await pgPool.query('CREATE TABLE IF NOT EXISTS app_state (key text PRIMARY KEY,data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT NOW())');
   const row=(await pgPool.query('SELECT data FROM app_state WHERE key=$1',[APP_NAMESPACE])).rows[0];
   if(row?.data){db=Object.assign(emptyDb(),row.data);normalizeAllRooms();}
   else await save();
   console.log('Database: PostgreSQL');
  }catch(e){pgPool=null;console.error('PostgreSQL unavailable, using file DB:',e.message)}
 }
 server.listen(PORT,'0.0.0.0',()=>console.log(`Xena Web listening on 0.0.0.0:${PORT}`));
}
bootstrap();
